<script setup lang="ts">
import { ref,shallowRef,computed,watch,nextTick,onMounted,onBeforeUnmount } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import { t,language,toggleLanguage,displayStatus } from '../i18n'
import zhCn from 'element-plus/es/locale/lang/zh-cn'
import en from 'element-plus/es/locale/lang/en'
import { workApi,downloadFile } from '../workApi'
import { usePlanStore } from '../stores/planStore'
import { CanvasAdapter } from '../adapter/CanvasAdapter'
import { createNode } from '../../../shared/plan.js'
import { REQUIREMENT_PRESETS } from '../../../shared/workflowPresets.js'
import { WORKFLOW_TEMPLATES } from '../../../shared/workflowTemplates.js'
import GoalEditor from '../components/GoalEditor.vue'
import WorkflowNodeEditor from '../components/WorkflowNodeEditor.vue'
import InfrastructurePanel from '../components/InfrastructurePanel.vue'
import AuditPanel from '../components/AuditPanel.vue'
import '../workbench.css'
const store=usePlanStore(),page=ref('design'),designTab=ref('graph'),canvas=ref<HTMLElement>(),adapter=shallowRef<CanvasAdapter>(),selected=ref('')
const busy=ref(false),error=ref(''),source=ref('# 发票核对\n## 目标\n校验发票并导出报告\n## 功能需求\n- FR-01: 校验发票编号\n- FR-02: 生成核对报告\n## 验收标准\n- AC-01: FR-01 重复编号被识别\n- AC-02: FR-02 生成报告文件'),inputMode=ref('structured'),goal=ref<any>(null)
const exportKind=ref('markdown'),presetId=ref('invoice')
const template=ref('rapid'),permission=ref('supervised'),caps=ref<any[]>([]),plans=ref<any[]>([]),versions=ref<any[]>([]),diagnostics=ref<any[]>([]),impact=ref<any>(null),trial=ref<any>(null),versionId=ref(''),workspaceId=ref(''),workspaces=ref<any[]>([]),run=ref<any>(null)
const controls=ref({human:false,security:false,qa:false,maxConcurrency:3,maxReworkIterations:2,budgetUsd:2.5,capabilityId:'simulated',qaCapabilityId:'native-api'})
const plan=computed(()=>store.plan as any),graph=computed(()=>page.value==='run'&&run.value?run.value.graph:plan.value),node=computed(()=>graph.value?.nodes.find((n:any)=>n.id===selected.value)),isActive=computed(()=>run.value&&['RUNNING','WAITING_HUMAN','PAUSED'].includes(run.value.status))
const fieldsInput=ref('{}'),reason=ref(''),session=ref<any>(null),sessionSelect=ref(''),logFilter=ref('all'),ghostOpen=ref(false),ghost=ref<any>({title:'',reason:'',targetId:'',capabilityId:'simulated',fileScope:'',command:'',args:'[]',prompt:''})
const showPalette=ref(false),paletteQuery=ref(''),fileInput=ref<HTMLInputElement>(),jsonInput=ref<HTMLInputElement>()
const edgeDraft=ref({source:'',target:'',kind:'dep',label:''}),collapsed=ref<Record<string,boolean>>({})
let timer:ReturnType<typeof setTimeout>|undefined,impactTimer:ReturnType<typeof setTimeout>|undefined,previous:any,impactEpoch=0,disposed=false
const clone=(v:any)=>JSON.parse(JSON.stringify(v))
async function safe(fn:()=>any){busy.value=true;error.value='';try{return await fn()}catch(e:any){error.value=e.response?.data?.message||e.message;ElMessage.error(error.value);if(Array.isArray(e.response?.data?.details))diagnostics.value=e.response.data.details}finally{busy.value=false}}
async function refresh(){const data=await Promise.all(['/capabilities','/plans','/workspaces'].map(p=>workApi.get(p)));caps.value=data[0].data;plans.value=data[1].data;workspaces.value=data[2].data}
async function parse(){goal.value=(await workApi.post('/goals/parse',{text:source.value,mode:inputMode.value})).data.goalSpec;designTab.value='requirements'}
function installPlan(p:any){clearTimeout(impactTimer);impactEpoch++;store.replace(p);goal.value=clone(p.workflow.goalSpec);selected.value='';diagnostics.value=[];impact.value=null;trial.value=null;versions.value=[];versionId.value='';previous=clone(p);designTab.value='graph'}
async function compile(){if(!goal.value)await parse();const {data}=await workApi.post('/workflows/compile',{goalSpec:goal.value,options:{template:template.value,permissionTier:permission.value,...controls.value}});installPlan(data.plan);diagnostics.value=data.diagnostics;await save();await nextTick();adapter.value?.fit()}
async function demo(){const {data}=await workApi.post('/workflows/demo',{human:true});installPlan(data.plan);workspaceId.value=data.workspace.id;permission.value='strict';await save();await refresh();ElMessage.success(t('已创建真实产物演示，可先试运行再发布','Artifact demo created. Run a trial, then publish.'))}
async function save(){await store.save();await loadVersions();plans.value=(await workApi.get('/plans')).data}
async function loadVersions(){if(!plan.value?.id)return;versions.value=(await workApi.get(`/plans/${plan.value.id}/versions`)).data;if(!versionId.value&&versions.value.length)versionId.value=versions.value[0].id}
async function openPlan(id:string){await store.load(id);goal.value=clone(plan.value.workflow?.goalSpec||null);previous=clone(plan.value);trial.value=(await workApi.get(`/plans/${id}/trial`)).data;versionId.value='';await loadVersions();page.value='design';designTab.value='graph'}
async function validate(){diagnostics.value=(await workApi.post('/workflows/validate',plan.value)).data.diagnostics;adapter.value?.setIssues(diagnostics.value)}
async function trialRun(){clearTimeout(impactTimer);impactEpoch++;await save();trial.value=(await workApi.post(`/plans/${plan.value.id}/trial`,{})).data;diagnostics.value=trial.value.diagnostics;designTab.value='validation'}
async function publish(){await save();const {data}=await workApi.post(`/plans/${plan.value.id}/versions`,{digest:trial.value?.digest});await loadVersions();versionId.value=data.id;ElMessage.success(`${t('已发布','Published')} ${data.tag}`)}
async function start(){if(!versionId.value)throw new Error(t('请先试运行并发布版本','Trial and publish a version first'));const {data}=await workApi.post(`/plans/${plan.value.id}/execute`,{versionId:versionId.value,workspaceId:workspaceId.value||undefined,inputs:JSON.parse(fieldsInput.value)});await openRun(data.runId)}
async function openRun(id:string){clearTimeout(timer);run.value=(await workApi.get(`/runs/${id}`)).data;localStorage.setItem('vto.workbench.run',id);page.value='run';selected.value='';session.value=null;await nextTick();adapter.value?.fit();schedulePoll()}
function schedulePoll(){clearTimeout(timer);if(!disposed&&isActive.value)timer=setTimeout(()=>void poll(),500)}
async function poll(){if(!run.value)return;try{const id=run.value.id,{data}=await workApi.get(`/runs/${id}`,{params:{since:run.value.logs.at(-1)?.seq||0}});if(run.value?.id!==id||disposed)return;const known=new Set(run.value.logs.map((l:any)=>l.seq));data.logs=[...run.value.logs,...data.logs.filter((l:any)=>!known.has(l.seq))];run.value=data}catch(e:any){error.value=e.response?.data?.message||e.message}finally{schedulePoll()}}
async function action(name:string,body:any={}){const id=run.value.id;if(name==='cancel'){await workApi.post(`/runs/${id}/cancel`);await poll()}else{run.value=(await workApi.post(`/runs/${id}/${name}`,body)).data;schedulePoll()}}
async function decision(item:any,actionName:string){if(!reason.value.trim())throw new Error(t('请填写决定理由','Enter a decision reason'));await action('resolve',{interventionId:item.id,action:actionName,reason:reason.value});reason.value=''}
async function inject(){await action('ghost',{...ghost.value,args:JSON.parse(ghost.value.args),fileScope:ghost.value.fileScope.split(/[,，\s]+/).filter(Boolean)});ghostOpen.value=false}
async function exportDesign(){const {data}=await workApi.post('/workflows/export',plan.value);const kind=exportKind.value;downloadFile(`workflow-plan.${kind==='markdown'?'md':kind==='mermaid'?'mmd':'json'}`,data[kind],kind==='json'?'application/json':'text/plain')}
async function exportEvidence(){downloadFile(`evidence-${run.value.id}.json`,(await workApi.get(`/runs/${run.value.id}/evidence`)).data)}
function select(id:string){selected.value=id;adapter.value?.focus(id)}
function patch(props:any){store.mutate(p=>{const n=p.nodes.find(n=>n.id===selected.value);if(n)n.props=props})}
function remove(){store.mutate(p=>{p.nodes=p.nodes.filter(n=>n.id!==selected.value);p.edges=p.edges.filter(e=>e.source!==selected.value&&e.target!==selected.value)});selected.value=''}
function addTask(){const parent=plan.value.workflow.groups.find((g:any)=>g.kind==='task')||plan.value.workflow.groups[0],phase=parent.kind==='task'?parent.parentId:parent.id,n=createNode('task',120,120);n.props={...n.props,name:t('新任务','New task'),executorKind:'tool',capabilityId:'simulated',planningRationale:t('请说明新增任务的原因','Explain why this task is needed'),requirementRefs:[],acceptanceRefs:[],inputContract:[],outputContract:[],fileScope:[],parentId:parent.id,phaseId:phase,depth:parent.kind==='task'?2:1};store.mutate(p=>p.nodes.push(n));selected.value=n.id}
function addEdge(){store.mutate(p=>p.edges.push({id:`edge_${Date.now()}`,source:edgeDraft.value.source,target:edgeDraft.value.target,kind:edgeDraft.value.kind,...(edgeDraft.value.label?{label:edgeDraft.value.label}:{})}));void safe(validate)}
function updateGoal(g:any){goal.value=g;if(plan.value.workflow)store.mutate((p:any)=>{p.workflow.goalSpec=clone(g)})}
async function sourceUpload(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(file){if(file.size>204800)throw new Error('200KB limit');source.value=await file.text()}}
async function importPlan(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;const p=JSON.parse(await file.text());if(!p.workflow)throw new Error(t('普通方案请使用原编辑器导入','Use the original editor for legacy plans'));await store.importPlan(p);goal.value=clone(p.workflow.goalSpec);await loadVersions()}
const groups=computed(()=>graph.value?.workflow?.groups||[])
const phaseGroups=computed(()=>groups.value.filter((g:any)=>g.kind==='phase'))
const filteredLogs=computed(()=>run.value?.logs.filter((l:any)=>logFilter.value==='all'||l.nodeId===selected.value)||[])
const commands=computed(()=>[{id:'design',name:t('设计工作台','Design studio')},{id:'run',name:t('运行控制','Run control')},{id:'infra',name:t('能力管理','Capabilities')},{id:'audit',name:t('证据审计','Evidence audit')}].filter(c=>c.name.toLowerCase().includes(paletteQuery.value.toLowerCase())))
watch(()=>template.value,id=>{const preset=WORKFLOW_TEMPLATES.find(p=>p.id===id);if(preset)Object.assign(controls.value,{human:preset.human,security:preset.security,qa:preset.qa,maxConcurrency:preset.maxConcurrency})})
watch(()=>store.plan,()=>{if(!plan.value.workflow)return;const next=clone(plan.value),before=previous;previous=next;clearTimeout(impactTimer);if(!before||before.id!==next.id)return;const epoch=++impactEpoch;impactTimer=setTimeout(async()=>{try{const {data}=await workApi.post('/workflows/impact',{before,after:next});if(epoch===impactEpoch){impact.value=data;if(data.requiresRetrial)trial.value=null;await validate()}}catch{}},350)},{deep:true})
watch(()=>[page.value,designTab.value,canvas.value],async()=>{adapter.value?.dispose();adapter.value=undefined;if(canvas.value&&graph.value?.nodes){adapter.value=new CanvasAdapter(canvas.value,clone(graph.value),{changed:p=>{if(page.value==='design')store.commit(p)},selected:id=>selected.value=id,notify:message=>ElMessage.warning(message),zoom:()=>{}});adapter.value.setLocked(page.value==='run');adapter.value.setStates(page.value==='run'?run.value.nodeStates:{});adapter.value.setIssues(diagnostics.value);adapter.value.fit()}},{flush:'post'})
watch(graph,(p,old)=>{if(adapter.value&&p){if(JSON.stringify(p)!==JSON.stringify(old))adapter.value.render(clone(p));adapter.value.setStates(page.value==='run'?run.value?.nodeStates||{}:{});adapter.value.setIssues(page.value==='design'?diagnostics.value:[])}},{deep:true})
watch(()=>run.value?.nodeStates,states=>{if(page.value==='run'&&states)adapter.value?.setStates(states)},{deep:true})
function keydown(e:KeyboardEvent){if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();showPalette.value=!showPalette.value}if(e.key==='Escape')showPalette.value=false}
onMounted(async()=>{window.addEventListener('keydown',keydown);await safe(async()=>{await refresh();if(!store.plan.workflow){try{const raw=localStorage.getItem('vto.workbench.draft');if(raw)installPlan(JSON.parse(raw))}catch{}}if(store.plan.workflow){goal.value=clone(store.plan.workflow.goalSpec);previous=clone(store.plan);await loadVersions()}const last=localStorage.getItem('vto.workbench.run');if(last){try{run.value=(await workApi.get(`/runs/${last}`)).data;schedulePoll()}catch{localStorage.removeItem('vto.workbench.run')}}})})
watch(()=>store.plan,p=>{if(p.workflow)localStorage.setItem('vto.workbench.draft',JSON.stringify(p))},{deep:true})
onBeforeUnmount(()=>{disposed=true;clearTimeout(timer);clearTimeout(impactTimer);adapter.value?.dispose();window.removeEventListener('keydown',keydown)})
</script>
<template><el-config-provider :locale="language==='zh'?zhCn:en"><div class="workbench">
 <header class="wb-header"><a class="wb-brand" href="#workbench"><span class="wb-logo">V</span><div>VTO <b>WORKBENCH</b><small>{{t('从需求到可验证的交付','From requirements to verified delivery')}}</small></div></a><nav><button v-for="item in [{id:'design',zh:'设计',en:'Design'},{id:'run',zh:'运行',en:'Run'},{id:'infra',zh:'能力',en:'Capabilities'},{id:'audit',zh:'审计',en:'Audit'}]" :class="{active:page===item.id}" @click="page=item.id">{{t(item.zh,item.en)}}</button></nav><div class="wb-header-actions"><button @click="showPalette=true">⌘ K</button><button @click="toggleLanguage">{{language==='zh'?'EN':'中文'}}</button><a href="#legacy">{{t('原编辑器','Classic editor')}} ↗</a></div></header>
 <div v-if="error" class="wb-error" role="alert">{{error}}<button @click="error=''">×</button></div>
 <main v-if="page==='design'" class="wb-design">
  <div class="wb-section-heading"><div><span class="wb-eyebrow">01 / {{t('设计与验证','DESIGN & VERIFY')}}</span><h1>{{plan.workflow?plan.name:t('将需求变成可执行计划','Turn requirements into an executable plan')}}</h1><p>{{t('编辑草稿，检查影响，试运行，再锁定版本。','Edit a draft, inspect impact, run a trial, then freeze a version.')}}</p></div><div class="wb-row"><select aria-label="Saved workflow" @change="safe(()=>openPlan(($event.target as HTMLSelectElement).value))"><option value="">{{t('打开工作流','Open workflow')}}</option><option v-for="p in plans" :value="p.id">{{p.name}}</option></select><el-button :loading="busy" @click="safe(demo)">{{t('真实产物演示','Artifact demo')}}</el-button><el-button @click="designTab='import'">{{t('导入需求','Import requirements')}}</el-button></div></div>
  <div class="wb-tabs"><button v-for="tab in [{id:'import',zh:'需求入口',en:'Import'},{id:'requirements',zh:'需求契约',en:'Goal contract'},{id:'graph',zh:'双模设计',en:'Design'},{id:'validation',zh:'校验与版本',en:'Validation & versions'}]" :class="{active:designTab===tab.id}" @click="designTab=tab.id">{{t(tab.zh,tab.en)}}</button><span class="wb-spacer"></span><template v-if="plan.workflow"><el-button :disabled="busy" @click="safe(save)">{{t('保存草稿','Save draft')}}</el-button><el-button :disabled="busy" @click="safe(trialRun)">{{t('隔离试运行','Isolated trial')}}</el-button><el-button type="primary" :disabled="busy||!trial?.passed" @click="safe(publish)">{{t('发布版本','Publish version')}}</el-button></template></div>
  <div v-if="designTab==='import'||!goal" class="wb-import-grid"><section class="wb-card"><h2>{{t('输入已确认的需求','Import confirmed requirements')}}</h2><div class="wb-row"><select v-model="inputMode" aria-label="Requirement input mode"><option value="structured">{{t('Markdown / 规则','Markdown / rules')}}</option><option value="natural">{{t('自然语言 / 模型','Natural language / model')}}</option></select><el-button @click="fileInput?.click()">{{t('上传文档','Upload document')}}</el-button><input ref="fileInput" type="file" accept=".md,.txt" hidden @change="safe(()=>sourceUpload($event))"/></div><div class="wb-row" style="margin-top:12px"><select v-model="presetId" aria-label="Requirement preset"><option v-for="p in REQUIREMENT_PRESETS" :value="p.id">{{p.name}}</option></select><el-button @click="source=REQUIREMENT_PRESETS.find(p=>p.id===presetId)?.text||source">{{t('填入示例','Use example')}}</el-button></div><textarea v-model="source" rows="17" aria-label="Requirement source" class="wb-source"/><p class="wb-muted">{{inputMode==='natural'?t('将调用已配置的模型；建议内容需要人工核对。','Uses the configured model; generated suggestions require review.'):t('离线提取字段，保留原文行号与来源。','Extracts fields offline and retains source lines.')}}</p><el-button type="primary" :loading="busy" @click="safe(parse)">{{t('提取需求契约','Extract goal contract')}}</el-button></section><section class="wb-card wb-intro"><span class="wb-eyebrow">GOAL → PLAN → RUN → EVIDENCE</span><h2>{{t('让每个决定都有依据','Give every decision a trace')}}</h2><p>{{t('需求编号连接任务与验收证据。运行绑定固定版本，草稿可继续编辑。','Requirement IDs connect tasks and evidence. Each run binds a frozen version while drafts remain editable.')}}</p><ol><li>{{t('核对 FR / AC 和来源','Review FR / AC and provenance')}}</li><li>{{t('检查三级诊断与变更影响','Check validation and change impact')}}</li><li>{{t('隔离试跑并发布不可变版本','Trial and freeze an immutable version')}}</li><li>{{t('执行、干预与导出证据','Execute, intervene and export evidence')}}</li></ol></section></div>
  <div v-else-if="designTab==='requirements'" class="wb-requirement-grid"><section class="wb-card"><GoalEditor :model-value="goal" @update:model-value="updateGoal"/></section><section class="wb-card"><h3>{{t('规划配置','Planning settings')}}</h3><label>{{t('模板','Template')}}<select v-model="template" aria-label="Workflow template"><option v-for="p in WORKFLOW_TEMPLATES" :value="p.id">{{p.name}}</option></select></label><label>{{t('权限策略','Permission tier')}}<select v-model="permission"><option>supervised</option><option>strict</option><option>turbo</option></select></label><label>{{t('任务执行能力','Task capability')}}<select v-model="controls.capabilityId"><option v-for="c in caps" :value="c.id">{{c.name}}</option></select></label><label>{{t('QA 执行能力','QA capability')}}<select v-model="controls.qaCapabilityId"><option v-for="c in caps.filter(c=>c.kind==='agent')" :value="c.id">{{c.name}}</option></select></label><div class="wb-checks"><el-checkbox v-model="controls.human">{{t('人工门禁','Human gate')}}</el-checkbox><el-checkbox v-model="controls.security">{{t('扩展验证路径','Extended verification route')}}</el-checkbox><el-checkbox v-model="controls.qa">{{t('独立 QA','Independent QA')}}</el-checkbox></div><label>{{t('最大并发','Maximum concurrency')}}<input type="number" v-model.number="controls.maxConcurrency" min="1" max="100"/></label><label>{{t('自动返工上限','Automatic rework limit')}}<input type="number" v-model.number="controls.maxReworkIterations" min="1" max="20"/></label><label>{{t('预算提示 USD','Budget notice USD')}}<input type="number" v-model.number="controls.budgetUsd" min="0" step="0.1"/></label><el-button type="primary" :loading="busy" @click="safe(compile)">{{t('编译任务与双图','Compile workflow')}}</el-button><p class="wb-muted">{{t('重新编译会生成新的草稿；已发布版本和运行不变。','Recompilation creates a new draft; published versions and runs remain intact.')}}</p></section></div>
  <template v-else-if="plan.workflow">
   <div v-if="impact?.requiresRetrial" class="wb-impact" data-testid="impact-report"><b>{{t('变更需要重新试运行','Changes require a new trial')}}</b><span>{{impact.affectedNodeIds.length}} {{t('个受影响节点','affected nodes')}} · {{impact.requirementIds.join(', ')||'—'}}</span></div>
   <div v-if="designTab==='graph'" class="wb-studio"><aside class="wb-tree"><div class="wb-row"><b>{{t('任务层级','Task hierarchy')}}</b><el-button size="small" @click="addTask">＋</el-button></div><details v-for="phase in phaseGroups" :key="phase.id" open><summary>{{phase.title}}</summary><template v-for="group in groups.filter((g:any)=>g.parentId===phase.id)"><details open><summary>{{group.title}}</summary><button v-for="n in graph.nodes.filter((n:any)=>n.props.parentId===group.id)" :class="{selected:selected===n.id}" @click="select(n.id)">{{n.props.name}}</button></details></template><button v-for="n in graph.nodes.filter((n:any)=>n.props.parentId===phase.id)" :class="{selected:selected===n.id}" @click="select(n.id)">{{n.props.name}}</button></details></aside><section class="wb-canvas-pane"><div class="wb-row wb-canvas-tools"><span>{{plan.nodes.length}} {{t('节点','nodes')}} · {{plan.edges.length}} {{t('连线','edges')}}</span><span class="wb-spacer"></span><button @click="store.undo">↶</button><button @click="store.redo">↷</button><button @click="safe(()=>{store.autoLayout();adapter?.fit()})">{{t('布局','Layout')}}</button><button @click="adapter?.fit()">{{t('适应','Fit')}}</button><button @click="safe(validate)">{{t('检查','Validate')}}</button></div><div ref="canvas" class="wb-canvas"/><details class="wb-edge-editor"><summary>{{t('表单编辑连线','Edit edges in form')}}</summary><div class="wb-row"><select v-model="edgeDraft.source" aria-label="Edge source"><option value="">{{t('来源','Source')}}</option><option v-for="n in plan.nodes" :value="n.id">{{n.props.name}}</option></select><select v-model="edgeDraft.target" aria-label="Edge target"><option value="">{{t('目标','Target')}}</option><option v-for="n in plan.nodes" :value="n.id">{{n.props.name}}</option></select><select v-model="edgeDraft.kind"><option v-for="kind in ['dep','pass','fail','loop']">{{kind}}</option></select><select v-model="edgeDraft.label"><option value="">—</option><option>true</option><option>false</option></select><el-button @click="addEdge">{{t('添加边','Add edge')}}</el-button></div><div v-for="e in plan.edges" :key="e.id" class="wb-entry"><small>{{plan.nodes.find((n:any)=>n.id===e.source)?.props.name}} → {{plan.nodes.find((n:any)=>n.id===e.target)?.props.name}} · {{e.kind}} {{e.label}}</small><button class="wb-link" @click="store.mutate(p=>{p.edges=p.edges.filter(x=>x.id!==e.id)})">×</button></div></details></section><aside class="wb-inspector"><WorkflowNodeEditor :node="node" :capabilities="caps" :groups="groups" @patch="patch" @remove="remove"/></aside></div>
   <div v-else class="wb-validation-grid"><section class="wb-card"><div class="wb-row"><h3>{{t('三级校验','Three-level validation')}}</h3><el-button @click="safe(validate)">{{t('重新检查','Revalidate')}}</el-button></div><div class="wb-metrics"><span v-for="level in ['error','warning','info']" :class="level"><b>{{diagnostics.filter(i=>(i.severity||'error')===level).length}}</b>{{level}}</span></div><button v-for="(d,i) in diagnostics" :key="i" class="wb-diagnostic" :class="d.severity||'error'" @click="designTab='graph';nextTick(()=>select(d.nodeId))"><b>{{d.rule}} · {{d.code||'STRUCTURE'}} · L{{d.level||1}}</b><span>{{d.message}}</span></button><div v-if="trial" class="wb-trial" data-testid="trial-report"><h3>{{trial.passed?t('试运行通过','Trial passed'):t('试运行未通过','Trial blocked')}}</h3><p>{{t('模拟路径，不执行目标工作区命令。','Simulated path; workspace commands were not invoked.')}}</p><small>{{trial.digest}}</small><div v-for="(step,i) in trial.steps" :key="i" class="wb-entry"><span>{{plan.nodes.find((n:any)=>n.id===step.nodeId)?.props.name}}</span><b>{{displayStatus(step.status)}}</b></div></div></section><section class="wb-card"><h3>{{t('不可变版本','Immutable versions')}}</h3><div v-for="v in versions" :key="v.id" class="wb-entry"><div><b>{{v.tag}}</b><small>{{new Date(v.createdAt).toLocaleString()}}</small></div><button class="wb-link" @click="downloadFile(`${v.tag}.json`,v)">{{t('下载快照','Download snapshot')}}</button></div><label>{{t('选择运行版本','Execution version')}}<select v-model="versionId" aria-label="Execution version"><option value="">—</option><option v-for="v in versions" :value="v.id">{{v.tag}} · {{v.plan.name}}</option></select></label><label>{{t('工作区','Workspace')}}<select v-model="workspaceId"><option value="">{{t('内置演示工作区','Built-in demo workspace')}}</option><option v-for="w in workspaces" :value="w.id">{{w.name}}</option></select></label><label>{{t('运行输入 JSON','Run inputs JSON')}}<textarea v-model="fieldsInput" rows="3"/></label><el-button type="primary" :disabled="!versionId||busy" @click="safe(start)">{{t('运行选定版本','Run selected version')}}</el-button><hr/><label>{{t('计划导出格式','Plan export format')}}<select v-model="exportKind" aria-label="Plan export format"><option value="markdown">Markdown WBS</option><option value="mermaid">Mermaid</option><option value="json">JSON</option></select></label><el-button @click="safe(exportDesign)">{{t('导出执行计划','Export execution plan')}}</el-button><el-button @click="store.exportPlan()">{{t('导出草稿 JSON','Export draft JSON')}}</el-button><el-button @click="jsonInput?.click()">{{t('导入 JSON','Import JSON')}}</el-button><input ref="jsonInput" type="file" hidden accept=".json" @change="safe(()=>importPlan($event))"/></section></div>
  </template>
 </main>
 <main v-else-if="page==='run'" class="wb-run"><template v-if="run"><div class="wb-section-heading"><div><span class="wb-eyebrow">02 / {{t('实时编排','LIVE ORCHESTRATION')}}</span><h1>{{run.planName}} <span class="wb-version">{{run.versionTag}}</span></h1><p><b data-testid="run-status">{{displayStatus(run.status)}}</b> · {{run.mode}} · {{run.id}}</p></div><div class="wb-row"><el-button v-if="['RUNNING','WAITING_HUMAN'].includes(run.status)" @click="safe(()=>action('pause'))">{{t('暂停','Pause')}}</el-button><el-button v-if="run.status==='PAUSED'" @click="safe(()=>action('resume'))">{{t('恢复','Resume')}}</el-button><el-button v-if="run.status==='FAILED'" @click="safe(()=>action('retry'))">{{t('重试失败节点','Retry failed nodes')}}</el-button><el-button :disabled="!isActive" @click="ghostOpen=true;ghost.targetId=run.graph.nodes.find((n:any)=>n.type==='end')?.id">＋ GhostNode</el-button><el-button :disabled="!isActive" type="danger" plain @click="safe(()=>action('cancel'))">{{t('取消运行','Cancel run')}}</el-button><el-button @click="safe(exportEvidence)">{{t('导出证据','Export evidence')}}</el-button></div></div>
 <div v-for="item in run.interventions?.filter((i:any)=>i.status==='open')" :key="item.id" class="wb-human" data-testid="human-gate"><div><b>{{t('需要人工决定','Human decision required')}}</b><p>{{item.question}}</p></div><input v-model="reason" aria-label="Decision reason" :placeholder="t('填写决定理由','Enter decision reason')"/><el-button type="primary" @click="safe(()=>decision(item,'approve'))">{{t('批准','Approve')}}</el-button><el-button v-if="item.kind!=='rework_limit'" @click="safe(()=>decision(item,'override'))">{{t('豁免','Waive')}}</el-button><el-button type="danger" plain @click="safe(()=>decision(item,'reject'))">{{t('拒绝','Reject')}}</el-button></div>
 <div class="wb-run-metrics"><div><small>{{t('完成节点','Completed nodes')}}</small><b>{{Object.values(run.nodeStates).filter((s:any)=>['SUCCESS','SKIPPED','WAIVED'].includes(s.status)).length}} / {{run.graph.nodes.length}}</b></div><div><small>{{t('资源槽','Worker slots')}}</small><b>{{run.resources?.activeWorkers||0}} / {{run.resources?.maxWorkers||0}}</b></div><div><small>{{t('自动返工','Automatic rework')}}</small><b>{{run.reworkCount}} / {{run.graph.workflow.maxReworkIterations}}{{run.extraReworkAllowance?` + ${run.extraReworkAllowance}`:''}}</b></div><div><small>{{t('估算费用 USD','Estimated cost USD')}}</small><b>{{run.usage?.estimatedCostUsd??0}}</b><small v-if="run.usage?.unknownAttempts">{{run.usage.unknownAttempts}} {{t('次用量/费率未知','attempts with unknown usage/rates')}}</small></div><div><small>Tokens · {{t('缓存','cached')}}</small><b>{{run.usage?.inputTokens||0}} / {{run.usage?.outputTokens||0}} · {{run.usage?.cachedTokens||0}}</b></div></div>
 <el-alert v-if="run.usage?.budgetExceeded" type="warning" :closable="false" :title="t('估算费用已超过预算提示线','Estimated cost exceeds the configured budget notice')"/>
 <div class="wb-studio wb-run-studio"><aside class="wb-tree"><details v-for="phase in phaseGroups" open><summary>{{phase.title}}</summary><button v-for="n in run.graph.nodes.filter((n:any)=>n.props.phaseId===phase.id)" :class="{selected:selected===n.id}" @click="select(n.id)"><span class="wb-state-dot" :class="run.nodeStates[n.id]?.status.toLowerCase()"></span>{{n.props.name}}<small>{{displayStatus(run.nodeStates[n.id]?.status)}}</small></button></details></aside><section class="wb-canvas-pane"><div class="wb-canvas-tools wb-row"><b>{{t('运行副本','Run snapshot')}}</b><span>{{t('版本不随草稿编辑变化','Draft edits do not change this version')}}</span><span class="wb-spacer"></span><button @click="adapter?.fit()">{{t('适应','Fit')}}</button></div><div ref="canvas" class="wb-canvas"/></section><aside class="wb-inspector"><template v-if="node"><h3>{{node.props.name}}</h3><p>{{node.props.planningRationale}}</p><p><code>{{node.props.requirementRefs?.join(', ')}}</code></p><p>{{displayStatus(run.nodeStates[node.id]?.status)}} · {{t('尝试','Attempt')}} {{run.nodeStates[node.id]?.attempt}}</p><el-button v-if="run.nodeStates[node.id]?.status==='FAILED'" @click="safe(()=>action('retry',{nodeId:node.id}))">{{t('重试此节点','Retry node')}}</el-button><details open><summary>{{t('尝试记录','Attempts')}}</summary><div v-for="a in run.attempts.filter((a:any)=>a.nodeId===node.id)" class="wb-attempt"><b>#{{a.number}} {{displayStatus(a.status)}}</b><p>{{a.output?.output||a.output||''}}</p></div></details><details><summary>{{t('契约详情','Contract details')}}</summary><pre>{{JSON.stringify({input:node.props.inputContract,output:node.props.outputContract},null,2)}}</pre></details></template><el-empty v-else :description="t('选择一个节点','Select a node')" :image-size="60"/></aside></div>
 <div class="wb-run-bottom"><section class="wb-card"><div class="wb-row"><h3>{{t('活动日志','Activity log')}}</h3><select v-model="logFilter"><option value="all">{{t('全部','All')}}</option><option value="node">{{t('选中节点','Selected node')}}</option></select></div><div class="wb-live-logs" data-testid="live-logs"><div v-for="l in filteredLogs" :key="l.seq" :class="l.event"><time>#{{l.seq}} {{new Date(l.time).toLocaleTimeString()}}</time><b>{{l.nodeName}}</b><span>{{l.message}}</span></div></div></section><section class="wb-card"><h3>{{t('检查点与恢复引用','Checkpoints & rescue refs')}}</h3><div v-for="cp in run.checkpoints" :key="cp.id" class="wb-checkpoint"><div><b>{{cp.label}}</b><small>{{cp.kind}} · {{cp.sha.slice(0,10)}}</small><code>{{cp.ref}}</code></div><el-button v-if="cp.kind==='checkpoint'" size="small" @click="safe(async()=>{await ElMessageBox.confirm(t('保存恢复前产物并切换到此检查点？','Preserve current artifacts and restore this checkpoint?'));await action('restore',{checkpointId:cp.id})})">{{t('恢复此点','Restore here')}}</el-button></div></section></div>
 <section class="wb-card"><h3>{{t('执行会话','Execution sessions')}}</h3><select v-model="sessionSelect" aria-label="Session select" @change="safe(async()=>{session=(await workApi.get(`/runs/${run.id}/sessions/${sessionSelect}`)).data})"><option value="">{{t('选择会话','Choose a session')}}</option><option v-for="s in run.sessions||[]" :value="s.id">{{run.graph.nodes.find((n:any)=>n.id===s.nodeId)?.props.name}} · {{s.id}}</option></select><div v-if="session"><p v-if="session.truncated">{{t('会话已达上限，内容截断','Transcript reached the size limit and was truncated')}}</p><div v-for="m in session.messages" class="wb-transcript"><b>{{m.role}}</b><pre>{{m.content}}</pre></div></div></section>
 </template><el-empty v-else :description="t('先发布一个工作流版本并启动运行','Publish a workflow version and start a run')"/></main>
 <main v-else-if="page==='infra'"><InfrastructurePanel/></main><main v-else><AuditPanel @open="id=>safe(()=>openRun(id))"/></main>
 <el-dialog v-model="ghostOpen" title="GhostNode" width="560px"><p>{{t('补充任务只进入当前运行，不修改发布版本。','The new task changes this run only, not the published version.')}}</p><label>{{t('插入目标之前','Insert before')}}<select v-model="ghost.targetId"><option v-for="n in run?.graph.nodes.filter((n:any)=>run.nodeStates[n.id].status==='PENDING'&&n.type!=='start')" :value="n.id">{{n.props.name}}</option></select></label><label>{{t('任务名称','Task name')}}<input v-model="ghost.title" aria-label="Ghost title"/></label><label>{{t('修改理由','Change reason')}}<textarea v-model="ghost.reason" aria-label="Ghost reason"/></label><label>{{t('能力','Capability')}}<select v-model="ghost.capabilityId"><option v-for="c in caps" :value="c.id">{{c.name}}</option></select></label><label>{{t('命令','Executable')}}<input v-model="ghost.command"/></label><label>{{t('参数 JSON','Arguments JSON')}}<input v-model="ghost.args"/></label><label>{{t('写入范围','Write scope')}}<input v-model="ghost.fileScope"/></label><template #footer><el-button @click="ghostOpen=false">{{t('取消','Cancel')}}</el-button><el-button type="primary" @click="safe(inject)">{{t('插入补充任务','Insert task')}}</el-button></template></el-dialog>
 <el-dialog v-model="showPalette" :title="t('快速导航','Quick navigation')" width="520px"><el-input v-model="paletteQuery" :placeholder="t('搜索页面','Search pages')"/><button v-for="c in commands" class="wb-command" @click="page=c.id;showPalette=false">{{c.name}} ↗</button></el-dialog>
</div></el-config-provider></template>
